'use strict';
const ATTACK_SCHEMES=['digits','zxc','auto'];
let attackScheme='digits',secondAttackScheme='digits890',autoAttackKeys='123',controlsOpen=false;
try{const saved=window.localStorage?.getItem('one-vs-one-attack-scheme');if(ATTACK_SCHEMES.includes(saved))attackScheme=saved}catch{}
function primaryAttackKeys(){return attackScheme==='auto'?autoAttackKeys:attackScheme==='zxc'?'zxc':'123'}
try{const saved=window.localStorage?.getItem('one-vs-one-second-attack-scheme');if(['digits890','iol'].includes(saved))secondAttackScheme=saved}catch{}
function secondaryAttackKeys(){return secondAttackScheme==='iol'?'iol':'890'}
function primaryAttackHeld(){return !controlsOpen&&keys.has(primaryAttackKeys()[0])}
function controlKey(e){if(/^Digit[012389]$/.test(e.code||'')||/^Numpad[012389]$/.test(e.code||''))return e.code.slice(-1);return (e.key||'').toLowerCase()}
function typingControl(e){return ['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)||e.target?.isContentEditable}
function handleGameKeyDown(e){if(controlsOpen){if(e.key==='Escape'){e.preventDefault();closeControls()}return}if(!running||typingControl(e)||e.ctrlKey||e.metaKey||e.altKey)return;const k=controlKey(e);if(!k)return;if(!e.repeat&&attackScheme==='auto'&&('123'.includes(k)||'zxc'.includes(k))){const next='zxc'.includes(k)?'zxc':'123';if(next!==autoAttackKeys){for(const oldKey of primaryAttackKeys())keys.delete(oldKey);autoAttackKeys=next;refreshControlSettings();if(fighters.length===2)renderAttackButtons(getMoves(fighters[localIndex()]))}}if(active()&&['arrowup','arrowdown','arrowleft','arrowright',' ','shift',...primaryAttackKeys(),...($('mode').value==='local'?[...secondaryAttackKeys(),'enter']:[])].includes(k))e.preventDefault();if(k==='escape'&&!e.repeat){pause();return}if(!active())return;keys.add(k);if(e.repeat)return;if(k==='shift'||k===' ')playerDodge();const slot=primaryAttackKeys().indexOf(k);if(slot>=0)playerAttack(slot);if($('mode').value==='local'){if(k==='enter')dodge(1);const other=secondaryAttackKeys().indexOf(k);if(other>=0)attack(1,other)}}
function handleGameKeyUp(e){keys.delete(controlKey(e))}
function setAttackScheme(value){if(!ATTACK_SCHEMES.includes(value))return false;attackScheme=value;clearInput();try{window.localStorage?.setItem('one-vs-one-attack-scheme',value)}catch{}refreshControlSettings();if(running&&fighters.length===2)renderAttackButtons(getMoves(fighters[localIndex()]));return true}
function refreshControlSettings(){$('attackScheme').value=attackScheme;const own=primaryAttackKeys().toUpperCase().split('').join(' / '),other=secondaryAttackKeys().toUpperCase().split('').join(' / ');$('secondAttackScheme').value=secondAttackScheme;$('attackSchemeHelp').textContent=(attackScheme==='auto'?'Auto: använd 123 eller ZXC. Knapparnas etiketter följer det du använder. ':'')+'Dina attacker: '+own+'. WASD flyttar, musen siktar och Shift undviker. Vänsterklick fungerar också för grundattacken.';$('desktopControls').textContent='Dator: WASD rörelse · musen siktar · '+own+' attacker · håll vänsterklick / '+primaryAttackKeys()[0].toUpperCase()+' för grundattack · Shift undvik.';$('localControls').textContent='Spelare 2: pilar rörelse · '+other+' attacker · Enter undvik. Siktar automatiskt mot spelare 1.';$('settingsLocalHelp').textContent='Två på samma tangentbord: spelare 2 använder '+other+'. Enter undviker. Båda valen sparas på den här enheten.'}
function setSecondAttackScheme(value){if(!['digits890','iol'].includes(value))return false;secondAttackScheme=value;clearInput();try{window.localStorage?.setItem('one-vs-one-second-attack-scheme',value)}catch{}refreshControlSettings();return true}
function openControls(){clearInput();if(active())pause();controlsOpen=true;const dialog=$('settingsDialog');if(dialog.showModal)dialog.showModal();else dialog.open=true;$('attackScheme').focus?.()}
function closeControls(){controlsOpen=false;const dialog=$('settingsDialog');if(dialog.close)dialog.close();else dialog.open=false;clearInput()}
function initControlSettings(){$('settingsOpen').onclick=openControls;$('settingsOpenGame').onclick=openControls;$('settingsClose').onclick=closeControls;$('attackScheme').onchange=()=>setAttackScheme($('attackScheme').value);$('secondAttackScheme').onchange=()=>setSecondAttackScheme($('secondAttackScheme').value);$('settingsDialog').addEventListener('cancel',e=>{e.preventDefault();closeControls()});refreshControlSettings()}
